// port of engine/src/platform/options.cpp policy,Repeat and geometry. Native containers/overlay/hints remain.
use std::ffi::{c_char,c_void,CStr};
type Sink=unsafe extern "C" fn(*mut c_void,*const u8,usize);
extern "C" {fn wprt_settings_keys(sink:Sink,context:*mut c_void);fn wphw_options_ui(out:*mut Ui);fn wphw_options_atoi(p:*const u8,n:usize)->i32;}
#[repr(C)]struct Ui{native:*const c_char,system:*const c_char,on:*const c_char,off:*const c_char}
unsafe fn bytes<'a>(p:*const u8,n:usize)->&'a[u8]{if n==0{&[]}else{std::slice::from_raw_parts(p,n)}}
// port of options.cpp known;settings::keys() enumeration remains the accepted implementation.
unsafe fn known(key:&[u8])->bool{struct Context<'a>{key:&'a[u8],found:bool}unsafe extern "C" fn visit(c:*mut c_void,p:*const u8,n:usize){let c=&mut *c.cast::<Context>();if c.key==bytes(p,n){c.found=true}}let mut c=Context{key,found:false};wprt_settings_keys(visit,(&mut c as *mut Context).cast());c.found}
// port of options.cpp enabled_text.
fn enabled(v:&[u8])->bool{![b"0".as_slice(),b"false",b"off",b"no"].contains(&v)}
// port of options.cpp live.
#[no_mangle]pub unsafe extern "C" fn wprt_options_live(p:*const u8,n:usize)->bool{LIVE.contains(&bytes(p,n))}
// port of options.cpp choices,including source short-circuit before known().
unsafe fn choices(k:&[u8])->Vec<Vec<u8>>{if k==b"video.scale"{return (1..=6).map(|i|i.to_string().into_bytes()).collect()}if k==b"system.interface_language"{return vec![b"en".to_vec(),b"es".to_vec(),b"gl".to_vec()]}if k==b"system.language"{return LANGUAGES.iter().map(|(k,_)|k.to_vec()).collect()}if k==b"saves.backups"{return COUNTS.iter().map(|v|v.to_vec()).collect()}if known(k){return vec![b"0".to_vec(),b"1".to_vec()]}Vec::new()}
#[no_mangle]pub unsafe extern "C" fn wprt_options_choices(p:*const u8,n:usize,sink:Sink,c:*mut c_void){for v in choices(bytes(p,n)){sink(c,v.as_ptr(),v.len())}}
// port of options.cpp shown_value;the source reads ui::text() exactly once at entry.
#[no_mangle]pub unsafe extern "C" fn wprt_options_shown(k:*const u8,kn:usize,v:*const u8,vn:usize,sink:Sink,c:*mut c_void){let k=bytes(k,kn);let v=bytes(v,vn);let mut ui=Ui{native:std::ptr::null(),system:std::ptr::null(),on:std::ptr::null(),off:std::ptr::null()};wphw_options_ui(&mut ui);let cs=|p|CStr::from_ptr(p).to_bytes().to_vec();let value=if k==b"video.scale"{if v==b"1"{cs(ui.native)}else{let mut out=v.to_vec();out.push(b'x');out}}else if k==b"system.interface_language"{if v==b"es"{b"Espa\xc3\xb1ol".to_vec()}else if v==b"gl"{b"Galego".to_vec()}else{b"English".to_vec()}}else if k==b"system.language"{match LANGUAGES.iter().find(|(code,_)|*code==v){Some((_,Some(name)))=>name.to_vec(),Some((_,None))=>cs(ui.system),None=>v.to_vec()}}else if k==b"saves.backups"{if v==b"0"{cs(ui.off)}else{v.to_vec()}}else{cs(if enabled(v){ui.on}else{ui.off})};sink(c,value.as_ptr(),value.len())}
// port of options.cpp step_value. Native atoi retains the source CRT parsing and locale behavior.
#[no_mangle]pub unsafe extern "C" fn wprt_options_step(k:*const u8,kn:usize,v:*const u8,vn:usize,step:i32,sink:Sink,c:*mut c_void){let k=bytes(k,kn);let v=bytes(v,vn);let list=choices(k);if list.is_empty(){sink(c,v.as_ptr(),v.len());return}let mut index=if let Some(i)=list.iter().position(|x|x==v){i as i32}else if list.len()==2&&list[0]==b"0"&&list[1]==b"1"{if enabled(v){1}else{0}}else if k==b"saves.backups"{let current=wphw_options_atoi(v.as_ptr(),v.len());let mut i=0;while i+1<list.len()&&wphw_options_atoi(list[i+1].as_ptr(),list[i+1].len())<=current{i+=1}i as i32}else{sink(c,list[0].as_ptr(),list[0].len());return};let count=list.len()as i32;index=((index.wrapping_add(step)%count)+count)%count;let result=&list[index as usize];sink(c,result.as_ptr(),result.len())}
// port of options.cpp Repeat::update;private C++ members are passed individually,not transmuted.
#[no_mangle]pub unsafe extern "C" fn wprt_options_repeat(held:u32,now:i64,repeating_mask:u32,delay:i64,interval:i64,previous:*mut u32,next:*mut i64)->u32{let pressed=held & !*previous;let mut fired=pressed;let repeating=held & *previous & repeating_mask;if pressed & repeating_mask!=0{*next=now.wrapping_add(delay)}else if repeating!=0&&now>=*next{fired|=repeating;*next=now.wrapping_add(interval)}*previous=held;fired}
#[repr(C)]#[derive(Clone,Copy,Default)]pub struct Layout{unit:i32,width:i32,height:i32,padding:i32,title_height:i32,row_height:i32,footer_height:i32,rows:usize}
#[repr(C)]#[derive(Clone,Copy,Default)]pub struct Rect{x:i32,y:i32,width:i32,height:i32}
#[repr(C)]pub struct Hover{pub row:i32,pub part:i32}
// port of options.cpp layout.
#[no_mangle]pub unsafe extern "C" fn wprt_options_layout(height:i32,rows:usize,out:*mut Layout){let unit=(height/40).clamp(14,40);let padding=unit+unit/2;let title_height=unit*3;let row_height=unit*2;let footer_height=unit*2+unit/2;*out=Layout{unit,width:unit*40,height:(padding*2+title_height).wrapping_add((rows as i32).wrapping_mul(row_height)).wrapping_add(footer_height),padding,title_height,row_height,footer_height,rows}}
// port of options.cpp place;ordered min matches std::min(initializer_list).
#[no_mangle]pub unsafe extern "C" fn wprt_options_place(cw:i32,ch:i32,w:i32,h:i32,out:*mut Rect){let mut r=Rect::default();if cw>0&&ch>0&&w>0&&h>0{let mut scale=1.0;let x=cw as f64/w as f64;let y=ch as f64/h as f64;if x<scale{scale=x}if y<scale{scale=y}r.width=1.max((w as f64*scale)as i32);r.height=1.max((h as f64*scale)as i32);r.x=(cw-r.width)/2;r.y=(ch-r.height)/2}*out=r}
// port of options.cpp row_at.
unsafe fn row_at(l:&Layout,p:&Rect,x:i32,y:i32)->i32{if p.width<=0||p.height<=0||l.row_height<=0{return -1}let bx=x.wrapping_sub(p.x)as i64*l.width as i64/p.width as i64;let by=y.wrapping_sub(p.y)as i64*l.height as i64/p.height as i64;let top=l.padding.wrapping_add(l.title_height)as i64;if x<p.x||y<p.y||bx<l.padding as i64||bx>=l.width.wrapping_sub(l.padding)as i64||by<top{return -1}let index=(by-top)/l.row_height as i64;if index<(l.rows as i64){index as i32}else{-1}}
#[no_mangle]pub unsafe extern "C" fn wprt_options_row(l:*const Layout,p:*const Rect,x:i32,y:i32)->i32{row_at(&*l,&*p,x,y)}
// port of options.cpp control_rect.
unsafe fn control(l:&Layout,row:usize)->Rect{let u=l.unit;let height=u.wrapping_mul(3)/2;let width=u.wrapping_mul(10);Rect{width,height,x:l.width.wrapping_sub(l.padding).wrapping_sub(u/2).wrapping_sub(width),y:l.padding.wrapping_add(l.title_height).wrapping_add((row as i32).wrapping_mul(l.row_height)).wrapping_add(l.row_height.wrapping_sub(height)/2)}}
#[no_mangle]pub unsafe extern "C" fn wprt_options_control(l:*const Layout,row:usize,out:*mut Rect){*out=control(&*l,row)}
// port of options.cpp close_rect.
unsafe fn close(l:&Layout)->Rect{let size=l.unit.wrapping_mul(2);Rect{width:size,height:size,x:l.width.wrapping_sub(l.padding).wrapping_sub(size),y:l.padding.wrapping_add(l.title_height.wrapping_sub(l.unit/2).wrapping_sub(size)/2)}}
#[no_mangle]pub unsafe extern "C" fn wprt_options_close(l:*const Layout,out:*mut Rect){*out=close(&*l)}
// port of options.cpp hit_test;Part values follow the original public enum.
#[no_mangle]pub unsafe extern "C" fn wprt_options_hit(l:*const Layout,p:*const Rect,x:i32,y:i32,out:*mut Hover){let l=&*l;let p=&*p;*out=Hover{row:-1,part:0};if p.width<=0||p.height<=0||x<p.x||y<p.y||x>=p.x.wrapping_add(p.width)||y>=p.y.wrapping_add(p.height){return}let bx=x.wrapping_sub(p.x)as i64*l.width as i64/p.width as i64;let by=y.wrapping_sub(p.y)as i64*l.height as i64/p.height as i64;let c=close(l);let margin=l.unit/2;if bx>=c.x.wrapping_sub(margin)as i64&&bx<c.x.wrapping_add(c.width).wrapping_add(margin)as i64&&by>=c.y.wrapping_sub(margin)as i64&&by<c.y.wrapping_add(c.height).wrapping_add(margin)as i64{(*out).part=5;return}let row=row_at(l,p,x,y);if row<0{return}*out=Hover{row,part:1};let c=control(l,row as usize);let top=l.padding.wrapping_add(l.title_height).wrapping_add(row.wrapping_mul(l.row_height));if bx>=c.x.wrapping_sub(margin)as i64&&bx<c.x.wrapping_add(c.width).wrapping_add(margin)as i64&&by>=top as i64&&by<top.wrapping_add(l.row_height)as i64{let arrow=l.unit.wrapping_mul(2);(*out).part=if bx<c.x.wrapping_add(arrow)as i64{2}else if bx>=c.x.wrapping_add(c.width).wrapping_sub(arrow)as i64{4}else{3}}}
